-- lovable-cron-fallback-reviewed: event-driven wake-on-enqueue; quarter-hour retries only while work remains; unscheduled on drain
CREATE TABLE public.drive_sync (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_table text NOT NULL, source_id uuid NOT NULL, doc_kind text NOT NULL, storage_path text NOT NULL, file_name text NOT NULL, drive_folder_id text, drive_folder_path text, drive_file_id text, drive_web_link text, status text NOT NULL DEFAULT 'pending', error text, attempts int NOT NULL DEFAULT 0, synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_table, source_id, doc_kind));
GRANT SELECT ON public.drive_sync TO authenticated;
GRANT ALL ON public.drive_sync TO service_role;
ALTER TABLE public.drive_sync ENABLE ROW LEVEL SECURITY;
CREATE POLICY drive_sync_read ON public.drive_sync FOR SELECT TO authenticated USING (public.auth_is_admin() OR public.auth_user_role() = 'coordinator');
CREATE TABLE public.drive_sync_settings (id int PRIMARY KEY DEFAULT 1 CHECK(id = 1), enabled boolean NOT NULL DEFAULT true, root_folder_id text NOT NULL DEFAULT '1-LXD1P-l3yhmSggZQkiHy_YrFj1Wodi3', kunder_folder_id text NOT NULL DEFAULT '1fkv371s0AV2gtnSOCM2FY3Vk2dUrDWcF', last_run_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.drive_sync_settings TO authenticated;
GRANT UPDATE(enabled, root_folder_id, kunder_folder_id) ON public.drive_sync_settings TO authenticated;
GRANT ALL ON public.drive_sync_settings TO service_role;
ALTER TABLE public.drive_sync_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY drive_settings_read ON public.drive_sync_settings FOR SELECT TO authenticated USING (public.auth_is_admin() OR public.auth_user_role() = 'coordinator');
CREATE POLICY drive_settings_admin_update ON public.drive_sync_settings FOR UPDATE TO authenticated USING (public.auth_is_admin()) WITH CHECK(public.auth_is_admin());
CREATE TRIGGER drive_sync_updated BEFORE UPDATE ON public.drive_sync FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER drive_settings_updated BEFORE UPDATE ON public.drive_sync_settings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.drive_sync_runtime (id int PRIMARY KEY DEFAULT 1 CHECK(id = 1), callback_url text, callback_bearer text, lease_owner uuid, lease_until timestamptz, generation bigint NOT NULL DEFAULT 0);
GRANT ALL ON public.drive_sync_runtime TO service_role;
ALTER TABLE public.drive_sync_runtime ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.drive_sync_claim(p_owner uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE g bigint; BEGIN UPDATE public.drive_sync_runtime SET lease_owner=p_owner, lease_until=now()+interval '4 minutes' WHERE id=1 AND (lease_until IS NULL OR lease_until<now()) RETURNING generation INTO g; RETURN g; END $$;
REVOKE ALL ON FUNCTION public.drive_sync_claim(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.drive_sync_claim(uuid) TO service_role;
CREATE FUNCTION public.drive_sync_wake() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE u text; b text; BEGIN IF NOT EXISTS(SELECT 1 FROM public.drive_sync_settings WHERE id=1 AND enabled) THEN RETURN; END IF; SELECT callback_url,callback_bearer INTO u,b FROM public.drive_sync_runtime WHERE id=1; IF u IS NULL OR b IS NULL THEN RETURN; END IF; PERFORM net.http_post(url:=u,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||b),body:='{"action":"run","limit":10}'::jsonb,timeout_milliseconds:=180000); IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='drive-sync-every-15-min') THEN PERFORM cron.schedule('drive-sync-every-15-min','*/15 * * * *','SELECT public.drive_sync_wake();'); END IF; END $$;
REVOKE ALL ON FUNCTION public.drive_sync_wake() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.drive_sync_wake() TO service_role;
CREATE FUNCTION public.drive_sync_finish(p_owner uuid,p_generation bigint,p_remaining boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n boolean; j bigint; BEGIN SELECT generation<>p_generation INTO n FROM public.drive_sync_runtime WHERE id=1 AND lease_owner=p_owner; IF NOT FOUND THEN RETURN; END IF; UPDATE public.drive_sync_runtime SET lease_owner=NULL,lease_until=NULL WHERE id=1 AND lease_owner=p_owner; IF p_remaining OR n THEN PERFORM public.drive_sync_wake(); ELSE FOR j IN SELECT jobid FROM cron.job WHERE jobname='drive-sync-every-15-min' LOOP PERFORM cron.unschedule(j); END LOOP; END IF; END $$;
REVOKE ALL ON FUNCTION public.drive_sync_finish(uuid,bigint,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.drive_sync_finish(uuid,bigint,boolean) TO service_role;
CREATE FUNCTION public.drive_sync_source_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h boolean:=false; BEGIN IF TG_TABLE_NAME='a_orders' THEN h:=NEW.status IN ('invoiced','credited') AND NEW.invoice_number IS NOT NULL AND NEW.pdf_path IS NOT NULL; ELSIF TG_TABLE_NAME='montor_debit_invoices' THEN h:=NEW.pdf_path IS NOT NULL; ELSIF TG_TABLE_NAME='case_documents' THEN h:=NEW.doc_type='mockfjards_payout' AND NEW.file_path IS NOT NULL; ELSIF TG_TABLE_NAME='uppdrag' THEN h:=NEW.handpenning_pdf_path IS NOT NULL OR NEW.slutfaktura_pdf_path IS NOT NULL; ELSIF TG_TABLE_NAME='offers' THEN h:=NEW.signed_pdf_path IS NOT NULL; END IF; IF h THEN UPDATE public.drive_sync_runtime SET generation=generation+1 WHERE id=1; PERFORM public.drive_sync_wake(); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.drive_sync_source_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER drive_sync_a_orders AFTER INSERT OR UPDATE OF pdf_path,invoice_number,status ON public.a_orders FOR EACH ROW EXECUTE FUNCTION public.drive_sync_source_changed();
CREATE TRIGGER drive_sync_montor AFTER INSERT OR UPDATE OF pdf_path ON public.montor_debit_invoices FOR EACH ROW EXECUTE FUNCTION public.drive_sync_source_changed();
CREATE TRIGGER drive_sync_payout AFTER INSERT OR UPDATE OF file_path,doc_type ON public.case_documents FOR EACH ROW EXECUTE FUNCTION public.drive_sync_source_changed();
CREATE TRIGGER drive_sync_uppdrag AFTER INSERT OR UPDATE OF handpenning_pdf_path,slutfaktura_pdf_path ON public.uppdrag FOR EACH ROW EXECUTE FUNCTION public.drive_sync_source_changed();
CREATE TRIGGER drive_sync_offer AFTER INSERT OR UPDATE OF signed_pdf_path ON public.offers FOR EACH ROW EXECUTE FUNCTION public.drive_sync_source_changed();